INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Wasserfallmodell immer Änderungen erlaubt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen sind nach Phasenabschluss schwierig"}, {"text": "Ja", "correct": false, "because": "Phasen sind festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Projekt mit dem V-Modell plane?', 3, '[{"text": "Testplanung", "correct": true, "because": "Tests sind für jede Phase definiert"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Qualität steht im Fokus"}, {"text": "Minimaler Dokumentation", "correct": false, "because": "Dokumentation ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen das Wasserfallmodell effektiv?', 5, '[{"text": "Klare Phasenstruktur", "correct": true, "because": "Definiert Ablauf genau"}, {"text": "Detaillierte Dokumentation", "correct": true, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Änderungen sind schwer"}, {"text": "Schnelle Iterationen", "correct": false, "because": "Phasen sind linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das V-Modell verknüpft Entwicklung und Tests. b) Es erlaubt jederzeit Änderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen sind eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Projekt mit dem Wasserfallmodell starte?', 4, '[{"text": "Anforderungsanalyse", "correct": false, "because": "Grundlage des Projekts"}, {"text": "Phasenplanung", "correct": false, "because": "Strukturiert Ablauf"}, {"text": "Teamgestaltung", "correct": true, "because": "Sekundär für Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das V-Modell für kleine Projekte geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Aufwand oft zu hoch"}, {"text": "Ja", "correct": false, "because": "Besser für komplexe Projekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Wasserfallmodell?', 3, '[{"text": "Vorhersehbare Ergebnisse", "correct": true, "because": "Phasen sind klar definiert"}, {"text": "Schnelle Anpassungen", "correct": false, "because": "Nicht flexibel"}, {"text": "Minimale Planung", "correct": false, "because": "Planung ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind beim V-Modell entscheidend?', 5, '[{"text": "Testen jeder Phase", "correct": true, "because": "Sichert Qualität"}, {"text": "Detaillierte Spezifikation", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Kurze Entwicklungszyklen", "correct": false, "because": "Nicht iterativ"}, {"text": "Wenig Dokumentation", "correct": false, "because": "Dokumentation ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Wasserfallmodell ist linear. b) Es ist ideal für agile Teams. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Agilität passt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Projekt mit dem V-Modell?', 4, '[{"text": "Testpläne", "correct": false, "because": "Kern des Modells"}, {"text": "Anforderungen", "correct": false, "because": "Grundlage des Projekts"}, {"text": "Spontane Änderungen", "correct": true, "because": "Modell ist starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Wasserfallmodell immer langsamer als agile Methoden?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt vom Projekt ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das V-Modell?', 4, '[{"text": "Hohe Qualitätssicherung", "correct": true, "because": "Tests für jede Phase"}, {"text": "Klare Struktur", "correct": true, "because": "Vermeidet Chaos"}, {"text": "Schnelle Iterationen", "correct": false, "because": "Nicht agil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das V-Modell keine Dokumentation braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation ist zentral"}, {"text": "Ja", "correct": false, "because": "Dokumentation ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Anforderungen im Wasserfallmodell zu definieren?', 3, '[{"text": "Pflichtenheft", "correct": true, "because": "Legt Spezifikationen fest"}, {"text": "Kurze Notizen", "correct": false, "because": "Zu ungenau"}, {"text": "Social Media", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Wasserfallmodell hat feste Phasen. b) Es passt für unsichere Anforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unsichere Anforderungen problematisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das V-Modell geeignet?', 5, '[{"text": "Hohe Sicherheitsanforderungen", "correct": true, "because": "Tests sichern Qualität"}, {"text": "Klare Anforderungen", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Modell ist starr"}, {"text": "Wenig Budget", "correct": false, "because": "Aufwand ist hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich das Wasserfallmodell nutze?', 3, '[{"text": "Phasenübergänge", "correct": false, "because": "Strukturieren Projekt"}, {"text": "Dokumentation", "correct": false, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Teamgestaltung", "correct": true, "because": "Kein Modellfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das V-Modell für dynamische Projekte ideal?', 3, '[{"text": "Nein", "correct": true, "because": "Besser für feste Anforderungen"}, {"text": "Ja", "correct": false, "because": "Flexibilität fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Wasserfallmodell für Prototypen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Prototypen brauchen Iterationen"}, {"text": "Ja", "correct": false, "because": "Modell ist linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich das V-Modell anwende?', 4, '[{"text": "Teststrategie", "correct": true, "because": "Sichert Qualität jeder Phase"}, {"text": "Schnelle Releases", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Minimaler Plan", "correct": false, "because": "Planung ist zentral"}]');
